// motorola_6800 full-ISA testbench.
//
// ISS vector replay: loads work/sim/mem.hex, runs from reset, and compares
// (pc, a, b, ix, sp, cc) at every opcode-fetch boundary against
// work/sim/vectors.hex (generated by scripts/make_isa_vectors.py from the
// independent Python oracle); final memory compared against gold_mem.hex.
//
// External interrupt events come from work/sim/triggers.hex: each record is
// (pc, action, delay) — when the core fetches at pc, the action fires after
// `delay` clocks: 0 = irq_n low, 1 = irq_n high, 2 = one-clock nmi_n pulse.
// A store of $AA to $E000 ends the run (the oracle's done marker).
`timescale 1ns/1ps

module tb_top;

    localparam int TCK = 100;
    localparam int MAXTRIG = 16;

    logic clk = 1'b0;
    always #(TCK/2) clk = ~clk;

    logic        rst_n;
    wire  [15:0] bus_addr;
    wire  [7:0]  bus_data_o;
    logic [7:0]  bus_data_i;
    wire         bus_we;
    wire         vma_o;
    logic        irq_n = 1'b1;
    logic        nmi_n = 1'b1;
    wire         halted_o, sync_o;
    wire  [15:0] pc_o, ix_o, sp_o;
    wire  [7:0]  a_o, b_o, cc_o;

    motorola_6800 dut (
        .clk, .rst_n, .bus_addr, .bus_data_i, .bus_data_o, .bus_we,
        .vma_o, .irq_n, .nmi_n, .halted_o, .sync_o,
        .pc_o, .a_o, .b_o, .ix_o, .sp_o, .cc_o
    );

    // ------------------------------------------------------------------
    // Memory
    // ------------------------------------------------------------------
    logic [7:0] mem  [0:65535];
    logic [7:0] gold [0:65535];

    always_comb begin
        bus_data_i = mem[bus_addr];
    end
    always_ff @(posedge clk) begin
        if (bus_we) mem[bus_addr] <= bus_data_o;
    end

    // ------------------------------------------------------------------
    // Vector file: pc a b ix sp cc per record
    // ------------------------------------------------------------------
    localparam int MAXVEC = 8000;
    logic [15:0] vec [0:6*MAXVEC];
    int          nvec;
    int          vidx = 0;
    int          checks = 0;
    int          errors = 0;

    // ------------------------------------------------------------------
    // Trigger file: pc action delay per record
    // ------------------------------------------------------------------
    logic [15:0] trig_flat [0:3*MAXTRIG];
    logic [15:0] trig_pc   [0:MAXTRIG];
    logic [15:0] trig_act  [0:MAXTRIG];
    logic [15:0] trig_dly  [0:MAXTRIG];
    int          ntrig;
    logic        fired     [0:MAXTRIG];
    int          countdown [0:MAXTRIG];
    logic        nmi_hold = 1'b0;

    task automatic fail(input string what);
        errors++;
        if (errors <= 20)
            $display("CHECK FAILED [%s] vidx=%0d at %0t: pc=%04x a=%02x b=%02x ix=%04x sp=%04x cc=%02x (expected %04x %02x %02x %04x %04x %02x)",
                     what, vidx, $time, pc_o, a_o, b_o, ix_o, sp_o, cc_o,
                     vec[vidx*6+0], vec[vidx*6+1], vec[vidx*6+2],
                     vec[vidx*6+3], vec[vidx*6+4], vec[vidx*6+5]);
    endtask

    integer i, k;
    initial begin
        $readmemh("work/sim/mem.hex", mem);
        $readmemh("work/sim/gold_mem.hex", gold);
        $readmemh("work/sim/vectors.hex", vec);
        $readmemh("work/sim/triggers.hex", trig_flat);
        nvec = 0;
        while (nvec < 6*MAXVEC && vec[nvec*6] !== 16'hFFFF) nvec++;
        ntrig = 0;
        while (ntrig < MAXTRIG && trig_flat[ntrig*3] !== 16'hxxxx) ntrig++;
        for (i = 0; i < ntrig; i++) begin
            trig_pc[i]  = trig_flat[i*3+0];
            trig_act[i] = trig_flat[i*3+1];
            trig_dly[i] = trig_flat[i*3+2];
            fired[i]    = 1'b0;
            countdown[i]= 0;
        end
        $display("loaded %0d vectors, %0d triggers", nvec, ntrig);
        rst_n = 1'b0;
        repeat (4) @(posedge clk);
        rst_n = 1'b1;
    end

    // ------------------------------------------------------------------
    // Boundary comparison: sample pre-edge state on every fetch
    // ------------------------------------------------------------------
    always_ff @(posedge clk) begin
        if (rst_n && sync_o && !done) begin
            if (vidx < nvec) begin
                if (pc_o !== vec[vidx*6+0] ||
                    {8'h00, a_o} !== vec[vidx*6+1] ||
                    {8'h00, b_o} !== vec[vidx*6+2] ||
                    ix_o !== vec[vidx*6+3] ||
                    sp_o !== vec[vidx*6+4] ||
                    {8'h00, cc_o} !== vec[vidx*6+5]) begin
                    fail("regs");
                end else begin
                    checks++;
                end
            end else begin
                fail("extra fetch beyond vector file");
            end
            vidx++;
        end
    end

    // ------------------------------------------------------------------
    // Trigger engine + done detection
    // ------------------------------------------------------------------
    logic done = 1'b0;
    int  done_at = 0;

    always_ff @(posedge clk) begin
        if (rst_n) begin
            for (k = 0; k < ntrig; k++) begin
                if (!fired[k] && sync_o && pc_o == trig_pc[k]) begin
                    fired[k]    <= 1'b1;
                    countdown[k]<= 32'(trig_dly[k]);
                end else if (fired[k] && countdown[k] > 0) begin
                    countdown[k] <= countdown[k] - 1;
                    if (countdown[k] == 1) begin
                        if (trig_act[k] == 16'd0) irq_n <= 1'b0;
                        else if (trig_act[k] == 16'd1) irq_n <= 1'b1;
                        else begin
                            nmi_n   <= 1'b0;
                            nmi_hold<= 1'b1;
                        end
                    end
                end
            end
            if (nmi_hold) begin
                nmi_n    <= 1'b1;
                nmi_hold <= 1'b0;
            end
            // $E000 control port (mirrors the oracle's io_write):
            // 0 = assert IRQ, 1 = deassert, 2 = NMI pulse, $AA = done
            if (bus_we && bus_addr == 16'hE000) begin
                if (bus_data_o == 8'h00) irq_n <= 1'b0;
                else if (bus_data_o == 8'h01) irq_n <= 1'b1;
                else if (bus_data_o == 8'h02) begin
                    nmi_n   <= 1'b0;
                    nmi_hold<= 1'b1;
                end
            end
            if (bus_we && bus_addr == 16'hE000 && bus_data_o == 8'hAA
                && !done) begin
                done    <= 1'b1;
                done_at = checks;
            end
        end
    end

    // ------------------------------------------------------------------
    // End of test: memory compare + verdict
    // ------------------------------------------------------------------
    int mdiff;
    initial begin
        wait (done);
        repeat (50) @(posedge clk);
        mdiff = 0;
        for (i = 0; i < 65536; i++)
            if (mem[i] !== gold[i]) begin
                if (mdiff < 10)
                    $display("MEM DIFF %04x: dut=%02x gold=%02x",
                             i, mem[i], gold[i]);
                mdiff++;
            end
        $display("boundary checks passed: %0d (of %0d vectors), done at check %0d",
                 checks, nvec, done_at);
        if (errors == 0 && mdiff == 0 && checks == nvec)
            $display("MC6800 FULL ISA TEST PASSED");
        else
            $display("MC6800 FULL ISA TEST FAILED: errors=%0d memdiff=%0d checks=%0d nvec=%0d",
                     errors, mdiff, checks, nvec);
        $finish;
    end

    // watchdog
    initial begin
        #200_000_000;
        $display("MC6800 FULL ISA TEST FAILED: watchdog timeout at vidx=%0d pc=%04x",
                 vidx, pc_o);
        $finish;
    end
endmodule
